// Une fonction sans paramètre ni valeur de retour
fn dire_bonjour() {
    println!("Bonjour !");
}

fn main() {
    dire_bonjour(); // on appelle la fonction par son nom
    dire_bonjour(); // on peut l'appeler autant de fois qu'on veut
}

// Deux paramètres typés, un type de retour i32
fn additionner(a: i32, b: i32) -> i32 {
    a + b // dernière expression sans point-virgule : c'est la valeur renvoyée
}

fn main() {
    let somme = additionner(3, 4); // somme vaut 7
    println!("La somme vaut {somme}");
}

fn doubler(x: i32) -> i32 {
    x * 2 // expression finale, PAS de point-virgule : la valeur est renvoyée
}

// Un bloc est lui-même une expression : sa dernière ligne sans `;` est sa valeur
fn main() {
    let y = {
        let base = 5;
        base + 1 // pas de point-virgule : le bloc vaut 6
    };
    println!("{y}");           // affiche : 6
    println!("{}", doubler(y)); // affiche : 12
}

fn main() {
    let note = 12;
    if note >= 10 {
        println!("Reçu");
    } else {
        println!("Ajourné");
    }
}

fn main() {
    let age = 20;
    // Les deux branches renvoient un &str : types compatibles
    let statut = if age >= 18 { "majeur" } else { "mineur" };
    println!("Statut : {statut}");
}

fn main() {
    // loop : on répète jusqu'à break, qui peut renvoyer une valeur
    let mut compteur = 0;
    let resultat = loop {
        compteur += 1;
        if compteur == 5 {
            break compteur * 2; // la boucle renvoie 10
        }
    };
    println!("loop renvoie {resultat}"); // affiche : 10

    // while : tant que la condition est vraie
    let mut n = 3;
    while n > 0 {
        println!("décompte : {n}");
        n -= 1;
    }

    // for : parcourt la plage 0..3 (0, 1, 2 ; 3 est exclu)
    for i in 0..3 {
        println!("tour numéro {i}");
    }
}

flowchart TD
  START["Je veux répéter du code"] --> Q{"Est-ce que je connais\nles éléments à parcourir ?"}
  Q -->|"Oui : une collection ou une plage 0..n"| FOR["for element in iterable\nle plus sûr et le plus courant"]
  Q -->|"Non, mais j'ai une condition d'arrêt"| W{"Je veux renvoyer\nune valeur en sortant ?"}
  W -->|"Non : tant que la condition est vraie"| WHILE["while condition"]
  W -->|"Oui : break valeur"| LOOP["loop { ... break valeur; }"]

sections.solution:
On teste d'abord le cas combiné (divisible par 3 ET par 5), car il doit avoir la priorité :

```rust
fn fizzbuzz() {
    for n in 1..=15 {               // 1 inclus jusqu'à 15 inclus
        if n % 3 == 0 && n % 5 == 0 {
            println!("FizzBuzz");   // on teste ce cas en premier
        } else if n % 3 == 0 {
            println!("Fizz");
        } else if n % 5 == 0 {
            println!("Buzz");
        } else {
            println!("{n}");        // ni l'un ni l'autre : on affiche le nombre
        }
    }
}

fn main() {
    fizzbuzz();
}
```

Point clé : l'ordre des tests compte. Si on testait `n % 3 == 0` avant le cas combiné, `15` afficherait `"Fizz"` au lieu de `"FizzBuzz"`.
